"""HeatBlock_exact: parametric CadQuery model generated by stl2cad (exact mode, 2.5D).

The part is built along +x from 3 extrusion(s) and 0 cut(s), applied in order;
each is an outline in the yz plane between two levels. Units: mm.
Run:  python HeatBlock_exact.py [out.step]
"""

import math
import sys

from cadquery import Edge, Solid, Vector
from cadquery import func as cf

# ---- parameters ----------------------------------------------------------
z0 = 0.0    # level along x
z1 = 10.0    # level along x
z2 = 65.0    # level along x
z3 = 75.0    # level along x

DIR = (1, 0, 0)


def P(a, b):
    """Point (y, z) in the sketch plane (x = 0)."""
    return (0, a, b)


def prism(outline, lo, hi):
    """Outline extruded from level lo to level hi."""
    body = cf.extrude(cf.face(outline), [(hi - lo) * c for c in DIR])
    return body.translate(Vector(*[lo * c for c in DIR]))


def hole(a, b, d, lo, hi):
    return prism(Edge.makeCircle(d / 2, P(a, b), DIR), lo, hi)


# ---- 1. extrusion: x 0.0 to 10.0 ------------------------------
outline_1 = cf.wire(
    cf.segment(P(0.0, 0.0), P(-100.0, -100.0)),
    cf.segment(P(-100.0, -100.0), P(-60.0, -100.0)),
    cf.segment(P(-60.0, -100.0), P(-60.0, -105.0)),
    cf.segment(P(-60.0, -105.0), P(-35.0, -105.0)),
    cf.segment(P(-35.0, -105.0), P(-35.0, -100.0)),
    cf.segment(P(-35.0, -100.0), P(0.0, -100.0)),
    cf.segment(P(0.0, -100.0), P(0.0, 0.0)),
)
part = prism(outline_1, z0, z1)

# ---- 2. extrusion: x 10.0 to 65.0 ------------------------------
outline_2 = cf.wire(
    cf.segment(P(0.0, 0.0), P(0.0, -100.0)),
    cf.segment(P(0.0, -100.0), P(-100.0, -100.0)),
    cf.segment(P(-100.0, -100.0), P(0.0, 0.0)),
)
part = part + prism(outline_2, z1, z2)

# ---- 3. extrusion: x 65.0 to 75.0 ------------------------------
outline_3 = cf.wire(
    cf.segment(P(0.0, 0.0), P(0.0, -100.0)),
    cf.segment(P(0.0, -100.0), P(-35.0, -100.0)),
    cf.segment(P(-35.0, -100.0), P(-35.0, -105.0)),
    cf.segment(P(-35.0, -105.0), P(-60.0, -105.0)),
    cf.segment(P(-60.0, -105.0), P(-60.0, -100.0)),
    cf.segment(P(-60.0, -100.0), P(-100.0, -100.0)),
    cf.segment(P(-100.0, -100.0), P(0.0, 0.0)),
)
part = part + prism(outline_3, z2, z3)

# ---- off-axis bosses and holes: (start point, axis direction, diameter, length) ----
for p, u, d, h, op in [
    ((37.5, 0.0, -25.0), (0.0, 1.0, 0.0), 25.0, 5.0, "add"),
]:
    c = Solid.makeCylinder(d / 2, h, Vector(*p), Vector(*u))
    part = part + c if op == "add" else part - c

part = part.clean()

if __name__ == "__main__":
    part.exportStep(sys.argv[1] if len(sys.argv) > 1 else "HeatBlock_exact.step")
